const htmlBody = $input.all()[0].json.html || '';
if (!htmlBody) throw new Error('No HTML body found in email.');

const hrefPattern = /href="(https:\/\/kyotogakuen1-my\.sharepoint\.com[^"]+)"/gi;
const links = [];
let match;
while ((match = hrefPattern.exec(htmlBody)) !== null) {
  links.push({ url: match[1], index: match.index });
}

if (links.length === 0) {
  throw new Error('No SharePoint links found.');
}

// Check surrounding context around each link to identify campus.
// We check AFTER the href too because the Halal link text ("ハラルフレンドリー...")
// comes after its href, and we need "ハラル" to exclude it from Uzumasa.
function getSurrounding(html, idx, before, after) {
  var s = Math.max(0, idx - before);
  var e = Math.min(html.length, idx + after);
  return html.substring(s, e);
}

function isHalal(ctx) {
  return ctx.indexOf('ハラル') !== -1 || ctx.indexOf('Halal') !== -1;
}

// Uzumasa: prefer English keyword ("Uzumasa"), fall back to Japanese ("太秦").
// Exclude the Halal-friendly link whose context touches the Uzumasa header.
var uzumasaLink = null;
for (var pass = 0; pass < 2 && !uzumasaLink; pass++) {
  var keyword = pass === 0 ? 'Uzumasa' : '太秦';
  for (var i = 0; i < links.length && !uzumasaLink; i++) {
    var ctx = getSurrounding(htmlBody, links[i].index, 200, 100);
    if (ctx.indexOf(keyword) !== -1 && !isHalal(ctx)) {
      uzumasaLink = links[i];
    }
  }
}

if (!uzumasaLink) {
  throw new Error('No Uzumasa campus link found in email.');
}

// SharePoint hands the weekly menus out as viewer links
// (":b:/r/…/onedrive.aspx?id=…"), and "?download=1" on those returns the
// OneDrive page instead of the file. download.aspx with the server-relative path
// is the endpoint that actually serves the PDF, so hand the fetcher that. Guest
// links (":b:/g/…", used for the Halal menus) are left exactly as they are.
function toDownloadUrl(u) {
  // n8n's Code sandbox has no URL/URLSearchParams, so parse by hand: a viewer
  // link's own "id" query parameter is the server-relative path of the file.
  var m = u.match(/^https:\/\/([^/]+)\/(?:.*\/)?personal\/([^/]+)\/.+?[?&]id=([^&]+)/i);
  if (!m) return u;
  return 'https://' + m[1] + '/personal/' + m[2] +
    '/_layouts/15/download.aspx?SourceUrl=' + encodeURIComponent(decodeURIComponent(m[3]));
}

return [
  { pdfUrl: toDownloadUrl(uzumasaLink.url), campus: 'Uzumasa' },
];

