const base64Pdf = $input.all()[0].json.base64Pdf;
if (!base64Pdf) throw new Error('No PDF returned from fetcher VM');

const campus = $('Extract PDF URL').all()[0].json.campus || 'Campus';

const now = new Date();
const weekOf = now.toISOString().slice(0, 10);

return { base64Pdf, campus, weekOf };

const responseData = $input.all()[0].json;

// Gemini returns: candidates[0].content.parts[0].text
const parts = responseData.candidates?.[0]?.content?.parts;
if (!parts || !parts[0]) throw new Error('No content in Gemini response');

const rawText = parts[0].text;
if (!rawText) throw new Error('No text in Gemini response');

const campus = $('Prepare PDF for Extraction').all()[0].json.campus || 'Uzumasa';

let dishes;
try {
  dishes = JSON.parse(rawText);
} catch(e) {
  const match = rawText.match(/```(?:json)?\\s*([\\s\\S]*?)```/);
  if (match) {
    dishes = JSON.parse(match[1].trim());
  } else {
    throw new Error('Parse failed: ' + e.message + '\\nRaw: ' + rawText.slice(0, 200));
  }
}

if (!Array.isArray(dishes)) throw new Error('Not an array');

// Staleness guard. On 2026-10-31 the subject line gained a campaign clause, the
// Gmail search fell back to the previous week's email, and this workflow
// re-wrote 2026-10-26..30 (as campus 'Unknown') while the week it was meant to
// scrape was never stored - the bot had nothing to post on 2026-11-02. A weekly
// menu is for the current or next week; anything older is a wrong email, so fail
// loudly instead of writing it again.
var menuDates = dishes
  .map(function (d) { return d.menu_date ? String(d.menu_date).slice(0, 10) : null; })
  .filter(Boolean)
  .sort();
var newestDate = menuDates[menuDates.length - 1];
if (newestDate) {
  var now = new Date();
  var day = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  var earliest = day - 1 * 86400000;
  var latest = day + 14 * 86400000;
  var newest = new Date(newestDate + 'T00:00:00Z').getTime();
  if (newest < earliest || newest > latest) {
    throw new Error(
      'Stale scrape: newest menu_date is ' + newestDate + ', expected ' +
      new Date(earliest).toISOString().slice(0, 10) + '..' +
      new Date(latest).toISOString().slice(0, 10) +
      '. The Gmail search matched an old email - check the subject filter in "Search Gmail" against this week\'s subject line.'
    );
  }
}
const weekOf = dishes[0]?.menu_date || new Date().toISOString().slice(0, 10);

return dishes
  .filter(d => d.dish_name && d.dish_name.trim() !== '')
  .map(d => ({
    campus,
    week_of: weekOf.slice(0, 10),
    day_name: d.day_name || null,
    menu_date: d.menu_date ? d.menu_date.slice(0, 10) : null,
    category: d.category || null,
    subcategory: d.subcategory || null,
    dish_name: d.dish_name,
    price: d.price ?? null,
    allergens: d.allergens || null,
    calories: d.calories || null,
    protein: d.protein || null,
    fat: d.fat || null,
    sodium: d.sodium || null,
  }));

// Pack every parsed row into one base64 blob for a single INSERT ... ON CONFLICT.
// Postgres raises a unique violation for *any* duplicate key in a multi-row
// INSERT, and the Halal poster repeats a whole month every run, so one row that
// already exists used to abort the entire batch and nothing new was ever stored.
const rows = $input
  .all()
  .map((item) => item.json)
  .filter((r) => r.dish_name && r.menu_date);

return [{ json: { rows_b64: Buffer.from(JSON.stringify(rows), 'utf8').toString('base64'), rows: rows.length } }];
